def solve_shortest_paths(graph, start_node):
    """
    Finds the shortest distance from a starting node to all other nodes in a weighted, directed graph.

    Args:
        graph: A dictionary representing the graph. Keys are node identifiers, and values are dictionaries
               representing outgoing edges. In these inner dictionaries, keys are neighbor node identifiers
               and values are the weights (costs) of the edges to those neighbors.
        start_node: The starting node identifier.

    Returns:
        A dictionary where keys are node identifiers and values are the calculated shortest distances
        from the start node. If a node is unreachable, its distance is infinity.
    """
    if not graph:
        return {start_node: 0} if start_node not in [node for sub_graph in graph for node in sub_graph] else {start_node:0}

    distances = {}
    for node in [node for sub_graph in graph for node in sub_graph] + [start_node]:
        distances[node] = float('inf')
    distances[start_node] = 0
    pq = [(0, start_node)]

    while pq:
        dist, current_node = heapq.heappop(pq)

        if dist > distances[current_node]:
            continue

        if current_node in [node for sub_graph in graph for node in sub_graph]:
            for neighbor, weight in [item for sub_graph in graph for node, item in sub_graph.items() if node == current_node]:
                new_dist = dist + weight
                if new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    heapq.heappush(pq, (new_dist, neighbor))

    if not all(value != float('inf') for value in distances.values()):
        return distances

    return distances

